it.each(['list-repositories','list-folders','create-project','inspect-connect','inspect-publish','publish-acknowledgment','issue-acknowledgment','close-acknowledgment'])('denies stale local admission after %s returns during shutdown',async operation=>{
 const {swarm,fake}=await office(true);const folder={name:'new',path:HOME_DIR,git:true,modified:0,github:'synthetic/new'};let action:()=>Promise<unknown>;
 if(operation==='list-repositories'){fake.listMyRepos.mockImplementationOnce(async()=>{await swarm.shutdown(true);return [];});action=()=>swarm.listGithubRepos();}
 else if(operation==='list-folders'){fake.scanProjects.mockImplementationOnce(async()=>{await swarm.shutdown(true);return [folder];});action=()=>swarm.listProjectFolders();}
 else if(operation==='create-project'){fake.createProject.mockImplementationOnce(async()=>{await swarm.shutdown(true);return {fullName:'synthetic/new',path:HOME_DIR};});action=()=>swarm.createRepo('new',{visibility:'private'});}
 else if(operation==='inspect-connect'||operation==='inspect-publish'){fake.inspectFolder.mockImplementationOnce(async()=>{await swarm.shutdown(true);return folder;});action=()=>operation==='inspect-connect'?swarm.connectFolder(HOME_DIR):swarm.publishFolder(HOME_DIR,{visibility:'private'});}
 else if(operation==='publish-acknowledgment'){fake.inspectFolder.mockResolvedValueOnce(folder);fake.publishFolder.mockImplementationOnce(async()=>{await swarm.shutdown(true);return 'synthetic/new';});action=()=>swarm.publishFolder(HOME_DIR,{visibility:'private'});}
 else if(operation==='issue-acknowledgment'){fake.createIssue.mockImplementationOnce(async()=>{await swarm.shutdown(true);return 9;});action=()=>swarm.createIssue('synthetic/repo','Scoped new issue','Synthetic');}
 else{fake.closePull.mockImplementationOnce(async()=>{await swarm.shutdown(true);});action=()=>swarm.closePull('synthetic/repo',7);}
 await expect(action()).rejects.toThrow('shutting down');expect(swarm.snapshot().repos).toHaveLength(1);expect(fake.startSession).not.toHaveBeenCalled();if(operation==='inspect-publish')expect(fake.publishFolder).not.toHaveBeenCalled();
});

it.each(['name','brief','model','effort','default-runtime','default-effort','mission','summary','qa-brief','linked-project','capability-contract','task-owner'])('revokes active worker tool authority after %s changes rather than applying stale admission',async change=>{
 const {swarm,fake}=await office(true);if(change==='linked-project')await swarm.connectRepo('synthetic/new',{localPath:HOME_DIR});let contract='original';swarm.workerAdmissionContext=()=>contract;const a=swarm.hireAgent('synthetic/repo',{});await swarm.assign(a.id,1);await vi.waitFor(()=>expect(fake.startSession).toHaveBeenCalledOnce());const opts=fake.startSession.mock.calls[0][0] as any;expect(await opts.authorizeTool()).toBeNull();
 if(change==='name')swarm.updateAgent(a.id,{name:'New name'});if(change==='brief')swarm.updateAgent(a.id,{brief:'Changed task instructions'});if(change==='model')swarm.updateAgent(a.id,{model:'gpt-synthetic'});if(change==='effort')swarm.updateAgent(a.id,{effort:'high'});if(change==='default-runtime')swarm.updateSettings({defaultCli:'gemini'});if(change==='default-effort')swarm.updateSettings({defaultEffort:'high'});if(change==='mission')swarm.updateRepo('synthetic/repo',{mission:'Changed mission'});if(change==='summary')swarm.updateRepo('synthetic/repo',{summary:'Changed scope profile'});if(change==='qa-brief')swarm.updateRepo('synthetic/repo',{qaBrief:'Changed acceptance profile'});if(change==='linked-project')swarm.updateRepo('synthetic/repo',{links:['synthetic/new']});if(change==='capability-contract')contract='changed';if(change==='task-owner')swarm.deliveryTaskContract=()=>({owner:'different',qaOwner:'independent',components:['app'],resources:[]});
 expect(await opts.authorizeTool()).toBeTruthy();expect(fake.startSession).toHaveBeenCalledOnce();
});
