it.each([true,false].flatMap(sameRepo=>['component','resource','separate'].flatMap(overlap=>[true,false].map(changeDeclaration=>({sameRepo,overlap,changeDeclaration})))))('keeps active claims scoped correctly: sameRepo=$sameRepo overlap=$overlap declarationChanged=$changeDeclaration',async({sameRepo,overlap,changeDeclaration})=>{
 const {swarm,fake}=await office(true,b=>b.listIssues.mockResolvedValue([issue,{...issue,number:2}]));if(!sameRepo)await swarm.connectRepo('synthetic/new',{localPath:HOME_DIR});const repo2=sameRepo?'synthetic/repo':'synthetic/new',a=swarm.hireAgent('synthetic/repo',{}),other=swarm.hireAgent(repo2,{});let firstComponents=['app'],firstResources=['shared-runtime'];
 swarm.deliveryTaskContract=(repoId,n)=>repoId==='synthetic/repo'&&n===1?{owner:a.id,qaOwner:'qa',components:firstComponents,resources:firstResources}:{owner:other.id,qaOwner:'qa',components:overlap==='component'?['app']:['other-app'],resources:overlap==='resource'?['shared-runtime']:['other-runtime']};
 await swarm.assign(a.id,1);await vi.waitFor(()=>expect(fake.startSession).toHaveBeenCalledOnce());if(changeDeclaration){firstComponents=['changed-declaration'];firstResources=['changed-resource'];}
 const blocked=overlap==='resource'||sameRepo&&overlap==='component';if(blocked){await expect(swarm.assign(other.id,2)).rejects.toThrow('active component/resource claim');expect(fake.startSession).toHaveBeenCalledOnce();swarm.stopAgent(a.id);await swarm.assign(other.id,2);}else await swarm.assign(other.id,2);
 await vi.waitFor(()=>expect(fake.startSession).toHaveBeenCalledTimes(2));expect(swarm.snapshot().agents.find(x=>x.id===other.id)?.issueNumber).toBe(2);
});


